using System.Text.RegularExpressions;
using InovaGed.Environment.Doctor.Quality;
namespace InovaGed.Environment.Doctor.Checks;
public sealed class SecurityQualityCheck : IQualityCheck
{
 public string Name=>"Security Scan";
 public async Task<IReadOnlyList<QualityFinding>> RunAsync(QualityContext c,CancellationToken ct){var findings=new List<QualityFinding>();var root=Path.Combine(c.Root,"InovaGed.Web");foreach(var file in Directory.EnumerateFiles(root,"*Controller.cs",SearchOption.AllDirectories)){var text=await File.ReadAllTextAsync(file,ct);var rel=Path.GetRelativePath(c.Root,file);if(!text.Contains("[Authorize",StringComparison.Ordinal)&&!text.Contains("AllowAnonymous",StringComparison.Ordinal))findings.Add(new(Name,QualityStatus.Warning,$"Controller sem declaração explícita de autorização: {rel}","Revisão de acesso necessária.","Adicionar política ou registrar rota pública em allowlist.",Resource:rel));foreach(Match action in Regex.Matches(text,@"\[HttpPost[^\]]*\](?<body>[\s\S]{0,500}?)(?=\[Http|$)"))if(!action.Groups["body"].Value.Contains("ValidateAntiForgeryToken",StringComparison.Ordinal))findings.Add(new(Name,QualityStatus.Fail,$"POST sem ValidateAntiForgeryToken: {rel}","Risco de CSRF.","Aplicar antiforgery na action.",Resource:rel));}foreach(var file in Directory.EnumerateFiles(root,"appsettings*.json")){var text=await File.ReadAllTextAsync(file,ct);if(Regex.IsMatch(text,"(?i)(password|pwd)\\s*=\\s*[^;]+")&&!text.Contains("${",StringComparison.Ordinal))findings.Add(new(Name,QualityStatus.Fail,$"Possível segredo em connection string: {Path.GetRelativePath(c.Root,file)}","Credencial pode ser exposta.","Mover o segredo para variável de ambiente."));}return findings.Count==0?[new(Name,QualityStatus.Pass,"Antiforgery, autorização e segredos estáticos sem violações detectadas.")]:findings;}
}
